(function(){
'use strict';
const KEY='panludiq.sound.v1';
let muted=false,volume=.35,saved=true,context=null,master=null,gestured=false,voices=[],last=0,available=true;
try{const value=JSON.parse(localStorage.getItem(KEY)||'null');if(value){muted=value.muted===true;if(Number.isFinite(value.volume))volume=Math.max(0,Math.min(1,value.volume))}}catch{saved=false}
const tones={select:[[560,0,.045]],correct:[[660,0,.09],[880,.085,.13]],wrong:[[220,0,.11],[165,.09,.14]],win:[[523,0,.12],[659,.1,.12],[784,.2,.12],[1047,.3,.2]],lose:[[330,0,.15],[262,.13,.15],[196,.26,.22]]};
function sync(){document.querySelectorAll('[data-sound-controls]').forEach(panel=>{panel.querySelector('summary').textContent=muted||volume===0?'소리 꺼짐':'소리 켜짐';panel.querySelector('[data-sound-enabled]').checked=!muted;panel.querySelector('[data-sound-volume]').value=String(Math.round(volume*100));panel.querySelector('output').textContent=Math.round(volume*100)+'%';panel.querySelector('[data-sound-note]').textContent=!available?'이 브라우저는 효과음을 지원하지 않아요.':!saved?'설정은 이번 페이지에서만 적용됩니다.':'첫 터치 후 재생 · 설정은 이 브라우저에 저장됩니다.'})}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({muted,volume}));saved=true}catch{saved=false}sync()}
function stop(){for(const voice of voices){try{voice.stop()}catch{}}voices=[]}
function unlock(event){if(!event.isTrusted)return;gestured=true;if(muted||volume===0||document.hidden)return;try{if(!context){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){available=false;sync();return}context=new Audio();master=context.createGain();master.gain.value=volume*.2;master.connect(context.destination)}if(context.state==='suspended')context.resume().catch(()=>{})}catch{available=false;sync()}}
function play(kind){if(!gestured||muted||volume===0||document.hidden||context?.state!=='running'||!tones[kind])return;const now=performance.now();if(kind==='select'&&now-last<55)return;last=now;stop();try{for(const [frequency,delay,duration] of tones[kind]){const oscillator=context.createOscillator(),gain=context.createGain(),start=context.currentTime+delay;oscillator.type='sine';oscillator.frequency.value=frequency;gain.gain.setValueAtTime(0,start);gain.gain.linearRampToValueAtTime(1,start+.008);gain.gain.exponentialRampToValueAtTime(.001,start+duration);oscillator.connect(gain);gain.connect(master);oscillator.onended=()=>{oscillator.disconnect();gain.disconnect();voices=voices.filter(v=>v!==oscillator)};voices.push(oscillator);oscillator.start(start);oscillator.stop(start+duration+.01)}}catch{stop()}}
function controls(){const panel=document.createElement('details');panel.className='sound-settings';panel.dataset.soundControls='';panel.innerHTML='<summary>소리 켜짐</summary><div class="sound-panel"><label><input type="checkbox" data-sound-enabled> 효과음 켜기</label><label class="sound-volume">볼륨 <output>35%</output><input type="range" min="0" max="100" step="5" data-sound-volume aria-label="효과음 볼륨"></label><button type="button" data-sound-test>소리 들어보기</button><p class="note" data-sound-note></p></div>';panel.querySelector('[data-sound-enabled]').addEventListener('change',e=>{muted=!e.target.checked;stop();if(master)master.gain.value=muted?0:volume*.2;persist()});panel.querySelector('[data-sound-volume]').addEventListener('input',e=>{volume=Number(e.target.value)/100;stop();if(master)master.gain.value=muted?0:volume*.2;persist()});panel.querySelector('[data-sound-test]').addEventListener('click',()=>play('correct'));panel.addEventListener('toggle',()=>{if(panel.open)document.querySelectorAll('[data-sound-controls]').forEach(other=>{if(other!==panel)other.open=false})});return panel}
window.Sound={play,stop};
for(const type of ['pointerdown','keydown','click'])document.addEventListener(type,unlock,true);
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
window.addEventListener('pagehide',stop);
document.addEventListener('click',event=>{const button=event.target.closest('[data-sound-select]');if(button&&!button.disabled)play('select');document.querySelectorAll('[data-sound-controls][open]').forEach(panel=>{if(!panel.contains(event.target))panel.open=false})});
const toolbar=document.createElement('div');toolbar.className='sound-toolbar';toolbar.appendChild(controls());document.querySelector('header').after(toolbar);
document.querySelectorAll('.dialog-head').forEach(head=>head.insertBefore(controls(),head.querySelector('.close')||head.querySelector('button')));sync();
})();
